  "routes.ts": "// routes.ts: isomorphic, imported by the browser (and a server, with SSR)\nimport { createRouter } from \"nuclo-router\";\nimport { announce } from \"./embed.ts\";\n\nexport const router = createRouter(\n  {\n    \"/\": () => import(\"./pages/Home.ts\"),\n    // A nested table: Docs is the layout, a topic renders in its outlet().\n    \"/docs\": {\n      \"/\": () => import(\"./pages/Docs.ts\"),\n      \"./:topic\": () => import(\"./pages/Topic.ts\"),\n    },\n    \"/blog/:slug\": () => import(\"./pages/Post.ts\"), // has a load()\n    \"/orders/new\": () => import(\"./pages/Order.ts\"), // opens a layer\n    \"/customers/new\": () => import(\"./pages/NewCustomer.ts\"),\n    \"*\": () => import(\"./pages/NotFound.ts\"),\n  },\n  {\n    base: \"/demos/router\", // the app lives under this prefix\n    onNavigate: (_ctx, kind) => announce(kind),\n  },\n);",
  "app.ts": "// app.ts: the layout. It places the outlet once and reads the router live.\nimport { router } from \"./routes.ts\";\nimport { s } from \"./styles.ts\";\n\nconst link = (href: string, label: string) =>\n  a(\n    { href: router.href(href) },\n    { \"aria-current\": () => (router.path === href ? \"page\" : \"\") },\n    label,\n  );\n\nexport const App = () =>\n  div(\n    s.app,\n    nav(\n      s.nav,\n      link(\"/\", \"Home\"),\n      link(\"/docs\", \"Docs\"),\n      link(\"/blog/hello-world\", \"Blog post\"),\n      link(\"/blog/broken\", \"Broken post\"),\n      link(\"/orders/new\", \"New order\"),\n      link(\"/missing\", \"404\"),\n    ),\n    main(\n      s.main,\n      when(() => router.pending, p(\"Loading…\")),\n      when(\n        () => router.error !== null,\n        div(\n          s.error,\n          p(() => `Failed: ${router.error?.message}`),\n          button(\"Retry\", {\n            onClick: () => router.go(router.url, { replace: true }),\n          }),\n        ),\n      ),\n      router.outlet(), // every page lands here; a layer is a row on top\n    ),\n    footer(\n      s.status,\n      () => `path ${router.path}  pattern ${router.pattern}`,\n      () => `  depth ${router.depth}`,\n    ),\n  );",
