  "pages/Home.ts": "import { router } from \"../routes.ts\";\n\nexport default function Home() {\n  return div(\n    h1(\"Home\"),\n    p(\n      \"A real nuclo-router app. Links are plain <a href>s; \",\n      \"the router owns the ones that match its table.\",\n    ),\n    p(\n      a({ href: router.href(\"/docs/intro\") }, \"Docs → intro\"),\n      \" · \",\n      a({ href: router.href(\"/blog/hello-world\") }, \"A post with a loader\"),\n      \" · \",\n      a({ href: router.href(\"/orders/new\") }, \"A form that opens a layer\"),\n    ),\n  );\n}",
  "pages/Docs.ts": "// Docs.ts: a layout page. Its child route renders inside outlet(), and\n// moving between topics never rebuilds this page: the input keeps its text.\nimport type { PageProps, RouteContext } from \"nuclo-router\";\nimport { router } from \"../routes.ts\";\nimport { s } from \"../styles.ts\";\n\nconst topics = [\"intro\", \"install\", \"api\"];\n\nexport default function Docs(_ctx: RouteContext, { outlet }: PageProps) {\n  return div(\n    h1(\"Docs\"),\n    div(\n      s.docs,\n      aside(\n        s.side,\n        // \"./intro\" resolves against this page's route: /docs/intro\n        ...topics.map((t) => a({ href: router.href(`./${t}`) }, t)),\n        input({ placeholder: \"Notes (kept)\" }),\n      ),\n      section(outlet()),\n    ),\n  );\n}",
  "pages/Topic.ts": "import type { Params, RouteContext } from \"nuclo-router\";\n\n// Params<pattern> types ctx.params from the pattern itself.\nexport default function Topic(ctx: RouteContext<Params<\"/docs/:topic\">>) {\n  return article(\n    h2(`Topic: ${ctx.params.topic}`),\n    p(`Rendered in the Docs layout's outlet. The layout was not rebuilt.`),\n    p(`Pattern ${ctx.pattern}, path ${ctx.path}.`),\n  );\n}",
  "pages/Post.ts": "// Post.ts: a page with a load(). It runs before the page is built, on every\n// visit, and whatever it returns arrives as `data`. While it runs,\n// router.pending is true and the previous page stays on screen.\nimport type { DataLoader, PageProps, RouteContext } from \"nuclo-router\";\n\ninterface Post { title: string; body: string }\n\nconst wait = (ms: number) => new Promise((r) => setTimeout(r, ms));\n\nexport const load: DataLoader<Post> = async (ctx) => {\n  await wait(700); // a slow API\n  if (ctx.params.slug === \"broken\") throw new Error(\"post not found\");\n  const title = ctx.params.slug.replace(/-/g, \" \");\n  return { title, body: \"Loaded by load() before the page was built.\" };\n};\n\nexport default function Post(\n  _ctx: RouteContext,\n  { data }: PageProps<Post>,\n) {\n  return article(h1(data.title), p(data.body));\n}",
  "pages/Order.ts": "// Order.ts: a form that needs a record that does not exist yet. push()\n// opens /customers/new as a layer on top, so this form is not re-rendered\n// and its text survives. Back closes the layer like Cancel does.\nimport type { PageProps, RouteContext } from \"nuclo-router\";\nimport { router } from \"../routes.ts\";\nimport { s } from \"../styles.ts\";\n\ninterface Customer { name: string }\n\nexport default function Order(_ctx: RouteContext, { layer }: PageProps) {\n  let customer: Customer | undefined;\n\n  return form(\n    h1(\"New order\"),\n    input({ placeholder: \"Notes: type, then open the layer\" }),\n    p(s.muted, () =>\n      customer ? `Customer: ${customer.name}` : \"No customer yet\",\n    ),\n    button(\"New customer…\", {\n      type: \"button\",\n      onClick: async () => {\n        // push() takes an href, so router.href() adds the base.\n        const created = await layer.push<Customer>(\n          router.href(\"/customers/new\"),\n        );\n        if (created) { customer = created; update(); }\n      },\n    }),\n  );\n}",
  "pages/NewCustomer.ts": "// NewCustomer.ts: the pushed page. close(result) resolves the push() that\n// opened it; close() with nothing is a dismissal. On a cold load there is\n// no layer beneath (layer.depth is 0), so it offers a link out instead.\nimport type { PageProps, RouteContext } from \"nuclo-router\";\nimport { router } from \"../routes.ts\";\nimport { s } from \"../styles.ts\";\n\nexport default function NewCustomer(\n  _ctx: RouteContext,\n  { layer }: PageProps,\n) {\n  let name = \"\";\n  return form(\n    s.layer,\n    h2(`New customer (layer depth ${layer.depth})`),\n    input({\n      placeholder: \"Name\",\n      onInput: (e) => { name = e.currentTarget.value; },\n    }),\n    button(\"Save\", {\n      type: \"button\",\n      onClick: () => layer.close({ name: name || \"Ada\" }),\n    }),\n    layer.depth > 0\n      ? button(\"Cancel\", { type: \"button\", onClick: () => layer.close() })\n      : a({ href: router.href(\"/orders/new\") }, \"Back to the order\"),\n  );\n}",
  "pages/NotFound.ts": "import type { RouteContext } from \"nuclo-router\";\nimport { router } from \"../routes.ts\";\n\n// The \"*\" route. A server answers these with a 404 status.\nexport default function NotFound(ctx: RouteContext) {\n  return div(\n    h1(\"Not found\"),\n    p(`Nothing matches ${ctx.path}.`),\n    a({ href: router.href(\"/\") }, \"Home\"),\n  );\n}",
